viewof rG  = Inputs.range([-3, 3],       {value: 0,    step: 0.1, label: "g (mm)"})
viewof rG0 = Inputs.range([-3, 3],       {value: 2,    step: 0.1, label: "g at x = 0 in (c) (mm)"})
viewof rEA = Inputs.range([0.5, 10],     {value: 2.7,  step: 0.1, label: "EA (×10⁹ N)"})












































rod = {
  const L = 10, K = rEA * 1e9, f = rF * 1e3, h = rH * 1e3, g = rG / 1e3, g0 = rG0 / 1e3;
  let u, du;
  if (rBC === "a") {
    u  = x =&gt; g + h / K * (L - x) + f / (2 * K) * (L * L - x * x);
    du = x =&gt; -h / K - f * x / K;
  } else if (rBC === "b") {
    u  = x =&gt; g + (h + f * L) / K * x - f / (2 * K) * x * x;
    du = x =&gt; (h + f * L) / K - f * x / K;
  } else {
    u  = x =&gt; g0 + (g - g0) * x / L + f / (2 * K) * x * (L - x);
    du = x =&gt; (g - g0) / L + f * (L - 2 * x) / (2 * K);
  }
  const N = x =&gt; K * du(x);
  const pts = d3.range(121).map(i =&gt; { const x = L * i / 120; return {x, u: 1e3 * u(x), N: N(x) / 1e3}; });
  return {L, K, f, h, u, du, N, pts};
}







